#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N = 1e5 + 10;

int n, m, a[N];

struct Node {
    ll sum, lazy;
} tr[N * 4];

void pushup(int u) {
    tr[u].sum = tr[u << 1].sum + tr[u << 1 | 1].sum;
}

void pushdown(int u, int lmid, int rmid) {
    if (tr[u].lazy) {
        tr[u << 1].sum += tr[u].lazy * lmid;
        tr[u << 1 | 1].sum += tr[u].lazy * rmid;
        tr[u << 1].lazy += tr[u].lazy;
        tr[u << 1 | 1].lazy += tr[u].lazy;
        tr[u].lazy = 0;
    }
}

void build(int u, int l, int r) {
    if (l == r) {
        tr[u] = {a[l], 0};
        return;
    }
    int mid = l + r >> 1;
    build(u << 1, l, mid);
    build(u << 1 | 1, mid + 1, r);
    pushup(u);
}

void modify(int u, int l, int r, int x, int y, int k) {
    if (x <= l && r <= y) {
        tr[u].sum += (ll)(r - l + 1) * k;
        tr[u].lazy += k;
        return;
    }
    int mid = l + r >> 1;
    pushdown(u, mid - l + 1, r - mid);
    if (x <= mid) modify(u << 1, l, mid, x, y, k);
    if (y > mid) modify(u << 1 | 1, mid + 1, r, x, y, k);
    pushup(u);
}

ll query(int u, int l, int r, int x, int y) {
    if (x <= l && r <= y) return tr[u].sum;
    int mid = l + r >> 1;
    pushdown(u, mid - l + 1, r - mid);
    ll res = 0;
    if (x <= mid) res += query(u << 1, l, mid, x, y);
    if (y > mid) res += query(u << 1 | 1, mid + 1, r, x, y);
    return res;
}

int main() {
    scanf("%d%d", &n, &m);
    for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
    build(1, 1, n);
    while (m--) {
        int op, x, y;
        scanf("%d%d%d", &op, &x, &y);
        if (op == 1) {
            int k;
            scanf("%d", &k);
            modify(1, 1, n, x, y, k);
        } else {
            printf("%lld\n", query(1, 1, n, x, y));
        }
    }
    return 0;
}

